import React, { Component } from 'react';
import { connect } from 'react-redux';
import { bindActionCreators } from 'redux';
import { ActionCreators } from '../actions';
import { Button, Col, Form, Modal, Row } from 'react-bootstrap';
import { Formik } from 'formik';
import FormikErrorMessage from '@jsroot/components/FormikErrorMessage';
import LangHelper from '@jsroot/common/langHelper';
import MultipleSelect from '../../../components/multiple-select/index';
import ResponseMessage from '@jsroot/components/ResponseMessage';
import DraggableModalDialog from '@jsroot/components/DraggableModalDialog';
import { renderSystemOption, validateFormik } from '../common.functions';

export class NewNotificationType extends Component {

    static defaultProps = {
        createNotificationTypeResult: {},
        settings: {
            recipientTypes: [],
            chatTypes: [],
            systems: []
        },
        getSettings: {}
    };

    constructor(props) {
        super(props);
    }

    renderForm = ({
        values,
        errors,
        touched,
        handleChange,
        handleSubmit,
        isSubmitting,
        setFieldValue
    }) => {

        return (
            <Form noValidate onSubmit={handleSubmit}>
                <Modal.Body>
                    <FormikErrorMessage touched={touched} errors={errors} fieldNames={Object.keys(values)} />
                    {
                        this.props.createNotificationTypeResult &&
                        <ResponseMessage isSuccessful={this.props.createNotificationTypeResult.isSuccessful}
                            message={this.props.createNotificationTypeResult.message || LangHelper.getResource('InsertNotificationTypeSuccessfully')}
                        />
                    }
                    <Form.Group as={Row}>
                        <Form.Label column sm="4" md="3" htmlFor="name" className="required">{LangHelper.getResource('NotificationTypeName')}</Form.Label>
                        <Col sm="8" md="9">
                            <Form.Control type="text" size="sm" value={values.notificationTypeName} name="notificationTypeName" id="name"
                                className="shadow-none" autoComplete="off"
                                onChange={handleChange}
                                isInvalid={touched.notificationTypeName && errors.notificationTypeName}
                            />
                        </Col>
                    </Form.Group>
                    <Form.Group as={Row}>
                        <Form.Label column sm="4" md="3" className="required">
                            {LangHelper.getResource('RecipientType')}
                        </Form.Label>
                        <Col sm="8" md="9">
                            <MultipleSelect
                                isInvalid={touched.recipientTypeIds && errors.recipientTypeIds}
                                dataSource={this.props.settings.recipientTypes}
                                keyField='id'
                                statusField='checked'
                                valueField='name'
                                isAllTextShown
                                onChange={(currentItem, selectedItemsKey) => {
                                    setFieldValue('recipientTypeIds', selectedItemsKey);
                                }}
                            />
                        </Col>
                    </Form.Group>
                    <Form.Group as={Row}>
                        <Form.Label column sm="4" md="3" className="required">{LangHelper.getResource('ChatType')}</Form.Label>
                        <Col sm="8" md="9">
                            <MultipleSelect
                                isInvalid={touched.chatTypeIds && errors.chatTypeIds}
                                dataSource={this.props.settings.chatTypes}
                                keyField='id'
                                statusField='checked'
                                valueField='name'
                                isAllTextShown
                                onChange={(currentItem, selectedItemsKey) => {
                                    setFieldValue('chatTypeIds', selectedItemsKey);
                                }}
                            />
                        </Col>
                    </Form.Group>
                    <Form.Group as={Row}>
                        <Form.Label column sm="4" md="3" value={values.systemId} className="required">
                            {LangHelper.getResource('System')}
                        </Form.Label>
                        <Col sm="8" md="9">
                            <Form.Control as="select" size="sm" className="shadow-none"
                                isInvalid={touched.systemId && errors.systemId}
                                name="systemId"
                                onChange={handleChange}
                                value={values.systemId}
                            >
                                <option value="" hidden>{LangHelper.getResource('PleaseSelect')}</option>
                                {this.props.settings.systems.map(renderSystemOption)}
                            </Form.Control>
                        </Col>
                    </Form.Group>
                </Modal.Body>
                <Modal.Footer>
                    <Button type="submit" variant="primary" size="sm" disabled={isSubmitting}>{LangHelper.getResource('Save')}</Button>
                    <Button type="submit" variant="primary" size="sm" onClick={this.props.onClose}>{LangHelper.getResource('Cancel')}</Button>
                </Modal.Footer>
            </Form>
        );
    };

    handleSubmit = (values, { setSubmitting }) => {
        const notificationType = {
            notificationTypeName: values.notificationTypeName,
            chatTypeIds: values.chatTypeIds,
            recipientTypeIds: values.recipientTypeIds,
            systemId: values.systemId
        };

        setSubmitting(true);
        this.props.createNotificationType(notificationType).then(() => {
            if (this.props.createNotificationTypeResult.isSuccessful) {
                setTimeout(() => {
                    this.props.onSuccess();
                }, 3000);
            } else {
                setSubmitting(false);
            }
        });
    };

    render() {
        const initialValues = {
            notificationTypeName: '',
            recipientTypeIds: '',
            chatTypeIds: '',
            systemId: ''
        };
        return (
            <Modal show className="new-notification-type" dialogAs={DraggableModalDialog}
                backdrop="static" keyboard={false} size="lg" centered
                onHide={this.props.onClose}
            >
                <Modal.Header closeButton>
                    <Modal.Title as="div">{LangHelper.getResource('InsertNotificationType')}</Modal.Title>
                </Modal.Header>
                <Formik
                    onSubmit={this.handleSubmit}
                    initialValues={initialValues}
                    validate={values => validateFormik(values)}
                >
                    {this.renderForm}
                </Formik>
            </Modal>
        );
    }
}

const mapDispatchToProps = dispatch => bindActionCreators(ActionCreators, dispatch);

const mapStateToProps = state => {
    const { createNotificationTypeResult, settings, getSettings } = state;
    return {
        createNotificationTypeResult,
        settings,
        getSettings
    };
};

export default connect(mapStateToProps, mapDispatchToProps)(NewNotificationType);